def f(g):
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]
    def ok(i,j):
        if g[i][j]!=2: return False
        for di in (-1,0):
            for dj in (-1,0):
                cells=[(i+di,j+dj),(i+di,j+dj+1),(i+di+1,j+dj),(i+di+1,j+dj+1)]
                if all(0<=a<h and 0<=b<w for a,b in cells):
                    if all(g[a][b]==3 for a,b in cells if (a,b)!=(i,j)): return True
        return False
    for i in range(h):
        for j in range(w):
            if ok(i,j):
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni,nj=i+di,j+dj
                        if 0<=ni<h and 0<=nj<w and g[ni][nj]!=2: o[ni][nj]=1
    return o
